import sys

sys.setrecursionlimit(200000)

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def maxPathSum(root):
    if root is None:
        return float('-inf')

    if root.left is None and root.right is None:
        return root.val

    left_sum = maxPathSum(root.left) if root.left else float('-inf')
    right_sum = maxPathSum(root.right) if root.right else float('-inf')

    current_max = max(left_sum, right_sum)
    if current_max == float('-inf'):
        return root.val

    return root.val + current_max

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    if n == 0:
        print(0)
        return

    nodes = {}
    roots = set()

    for _ in range(n):
        u = int(next(iterator))
        v_left = int(next(iterator))
        v_right = int(next(iterator))

        if u not in nodes:
            nodes[u] = Node(u)
        if v_left != -1:
            if v_left not in nodes:
                nodes[v_left] = Node(v_left)
            nodes[u].left = nodes[v_left]
        if v_right != -1:
            if v_right not in nodes:
                nodes[v_right] = Node(v_right)
            nodes[u].right = nodes[v_right]

    parents = set()
    for u in nodes:
        if nodes[u].left:
            parents.add(nodes[u].left)
        if nodes[u].right:
            parents.add(nodes[u].right)

    root_node = None
    for u in nodes:
        if nodes[u] not in parents:
            root_node = nodes[u]
            break

    if root_node is None and nodes:
        root_node = next(iter(nodes.values()))

    result = maxPathSum(root_node)
    print(result)

if __name__ == "__main__":
    main()
